    # String.num(..,4): emulate Godot minimal repr rounded to 4 decimals
    def fmt_num(v):
        s = repr(float(v))
        if 'e' in s or 'E' in s:
            return '%.4f' % float(v)
        if '.' in s:
            ip, fp = s.split('.')
            return ip + '.' + fp[:4]
        return s
